with FilteredOrderItems as (select * from order_items where unit_price >= 350 and order_id in (5, 18, 25)), Summary as (select case when unit_price >= 360 then 'high' when unit_price >= 190 then 'mid' else 'low' end as unit_price_bucket, avg(quantity) as avg_quantity from FilteredOrderItems group by case when unit_price >= 360 then 'high' when unit_price >= 190 then 'mid' else 'low' end) select * from Summary where avg_quantity >= 6.1
